function UserCard({ user, showEmail }: Props) {
  if (showEmail) {
    // Violation: hook inside condition
    const [copied, setCopied] = useState(false);
  }

  return <div>{user.name}</div>;
}

function useCopyEmail(email: string | null) {
  const [copied, setCopied] = useState(false);

  const copy = () => {
    if (!email) return;
    navigator.clipboard.writeText(email);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return { copied, copy };
}

function UserCard({ user, showEmail }: Props) {
  const { copied, copy } = useCopyEmail(showEmail ? user.email : null);
  // hooks are always called in the same order

  return <div>{user.name}</div>;
}

function useMousePosition() {
  const [pos, setPos] = useState({ x: 0, y: 0 });

  useEffect(() => {
    const handler = (e: MouseEvent) => setPos({ x: e.clientX, y: e.clientY });
    window.addEventListener('mousemove', handler);
    return () => window.removeEventListener('mousemove', handler);
  }, []);

  return pos;
}

function useDraggable(initial = { x: 0, y: 0 }) {
  const [offset, setOffset] = useState(initial);
  const mouse = useMousePosition();

  const startRef = useRef<typeof mouse | null>(null);

  const onMouseDown = () => { startRef.current = mouse; };
  const onMouseUp = () => { startRef.current = null; };

  useEffect(() => {
    if (!startRef.current) return;
    const dx = mouse.x - startRef.current.x;
    const dy = mouse.y - startRef.current.y;
    setOffset((prev) => ({ x: prev.x + dx, y: prev.y + dy }));
    startRef.current = mouse;
  }, [mouse]);

  return { ...offset, onMouseDown, onMouseUp };
}

/**
 * Listens to the online/offline status of the browser.
 *
 * @returns {OnlineStatus} An object with an `online` boolean and
 *   an `eventType` string describing the last change.
 *
 * @example
 * const { online } = useOnlineStatus();
 */
export function useOnlineStatus(): { online: boolean; eventType: 'online' | 'offline' } {
  const [online, setOnline] = useState(navigator.onLine);

  useEffect(() => {
    const goOnline = () => setOnline(true);
    const goOffline = () => setOnline(false);

    window.addEventListener('online', goOnline);
    window.addEventListener('offline', goOffline);

    return () => {
      window.removeEventListener('online', goOnline);
      window.removeEventListener('offline', goOffline);
    };
  }, []);

  return { online, eventType: online ? 'online' : 'offline' };
}

// React Component Example with Hooks
import React, { useState, useEffect, useCallback } from 'react';

function DataFetcher({ endpoint }) {
  // State management with useState
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // useCallback for memoized fetch function
  const fetchData = useCallback(async () => {
    try {
      setLoading(true);
      setError(null);

      const response = await fetch(endpoint);
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const result = await response.json();
      setData(result);
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  }, [endpoint]);

  // useEffect for side effects
  useEffect(() => {
    fetchData();
  }, [fetchData]);

  if (loading) return <div className="loading">Loading...</div>;
  if (error) return <div className="error">Error: {error}</div>;

  return (
    <div className="data-container">
      <h2>Fetched Data</h2>
      <pre>{JSON.stringify(data, null, 2)}</pre>
    </div>
  );
}

export default DataFetcher;
